"""Russian illustrated conference report based on the supervisor's revision."""
import json
from pathlib import Path
from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Pt
from pypdf import PdfReader
from build_learned_report import block,docx,pdf,ST

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output/report_revision_20261020'
SOURCE=Path('C:/Users/sha-b/Downloads/Telegram Desktop/ИТНТ_2027_Шабашев.docx')

def main():
    source=Document(SOURCE)
    assert source.paragraphs[1].text=='В. О. Шабашев'
    rows=json.loads((ROOT/'experiments/evidence/instance_v4/test_summary.json').read_text())
    r={x['method']:x for x in rows if x['delta']==.02}
    v={x['method']:x for x in json.loads((ROOT/'experiments/evidence/davis_v4/summary.json').read_text()) if x['subset']=='main_eval'}
    B=[]
    def add(kind,text=None,**kw):B.append(block(kind,text,**kw))
    add('title','Дополнительная текстовая проверка при поиске заданного экземпляра объекта по одному изображению')
    add('center',source.paragraphs[1].text)
    add('center',source.paragraphs[2].text)
    add('p','<b>Аннотация.</b> Рассматривается поиск конкретного экземпляра объекта по единственному эталонному изображению. Предлагается дополнять визуальное сопоставление сравнением текстовых описаний. На тесте изображений число ложных принятий уменьшилось со 123 до 110, а на видеокадрах число ложных рамок снизилось с 29 до 24. При этом число правильных решений также сократилось. Сравнение с ужесточённым визуальным порогом позволяет отделить пользу текста от эффекта увеличения числа отказов.')
    add('small','Ключевые слова: поиск объекта по образцу, текстовое описание, ложные принятия, расстояние Махаланобиса, полнота обнаружения.')
    add('head','1 Постановка задачи')
    add('p','Обычный детектор определяет, к какой категории относится объект: например, находит автомобиль или человека. В рассматриваемой задаче этого недостаточно. По одному эталонному снимку требуется найти именно показанный экземпляр, отличить его от похожих объектов и выдать его рамку либо отказаться от обнаружения. При обработке видео решение принимается для каждого кадра; начальная рамка цели алгоритму не задаётся. Общая модель может обучаться на других объектах, но дополнительные снимки тестовой цели не используются.')
    add('p','Ложное принятие означает, что другой экземпляр ошибочно признан целью. Такой результат считается в пять раз дороже пропуска. Цель исследования - проверить, может ли дополнительное описание внешнего вида уменьшить эти ошибки при потере полноты не более двух процентных пунктов. Ограничение полноты не позволяет добиться хорошего результата постоянным отказом. Для готовых вырезок проверяется идентичность экземпляра; для полных кадров дополнительно оценивается точность рамки.')
    add('head','2 Как выполняется текстовая проверка')
    add('p','Сначала сеть DINOv2-small [1] преобразует эталон и найденный кандидат в числовые признаки внешнего вида. Их сравнивают по косинусному расстоянию: меньшая величина соответствует большему сходству. Если визуально принятый кандидат попадает в заранее определённую область неоднозначности, включается дополнительная проверка (рис. 1).')
    add('image',path=OUT/'pipeline.png',height=90)
    add('small','Рисунок 1. Последовательность обработки. Описания эталона и кандидата формируются независимо; модель не получает правильный ответ о совпадении.')
    add('p','Визуально-языковая модель Qwen3.5:0.8b описывает каждый снимок словами. Модель all-MiniLM-L6-v2 семейства Sentence-BERT [2] переводит описание в числовой вектор. Затем обучаемая полносвязная сеть - проектор [3] - преобразует 384 признака в 64 через промежуточные слои размерности 256 и 128. Её обучают сближать представления одного экземпляра и разделять разные экземпляры. Используются тройки примеров: эталон, тот же объект и другой объект. Обучение длится 30 эпох; шаг оптимизации равен 0,001.')
    add('p','Расстояние Махаланобиса учитывает совместные изменения признаков. Для нормированных выходов проектора a и b оно определяется выражением')
    add('image',path=ROOT/'experiments/evidence/instance_v3/mahalanobis_formula.png',height=35)
    add('p','Матрица ковариации оценивается методом Ledoit-Wolf [4] только по обучающим парам одного экземпляра; добавка 10⁻⁴I обеспечивает регуляризацию. При слишком большом расстоянии кандидат отклоняется. Это общая метрика, перенесённая с других объектов: по единственному эталону отдельная ковариация цели не оценивается.')
    add('break');add('head','3 Данные и условия сравнения')
    add('p','Для основной проверки из Washington RGB-D [5] заранее выбраны 80 новых физических экземпляров 20 категорий: по 40 для настройки порогов и итогового теста, всего 400 изображений. Эталон и кандидаты получены из разных видео одного стенда. Тест включает 320 пар: 160 совпадений и 160 пар разных экземпляров одной категории. Таким образом, в отрицательных примерах сравниваются похожие предметы, а не заведомо различные категории. Обучение проектора выполнено на 920 изображениях 184 других экземпляров.')
    add('image',path=OUT/'examples.png',height=185)
    add('small','Рисунок 2. Реальные примеры из Washington RGB-D [5]: устранённое ложное принятие и добавленный пропуск. Выбраны первые подходящие случаи в сохранённом порядке пар; изображения увеличены для показа. Это иллюстрации, а не отдельная выборка для оценки.')
    add('p','Сравниваются три варианта: исходный визуальный метод без текста; тот же метод с более строгим порогом; исходный метод с текстовой проверкой. Второй вариант нужен, поскольку часть ложных принятий можно убрать простым увеличением числа отказов. Оба изменённых метода настраиваются при одинаковом ограничении полноты. Цена ошибок задаётся выражением J=(5FP+FN)/N, где FP - число ложных принятий, FN - пропусков, N - число решений.')
    add('p','Исходная полнота на проверочной выборке составила 91,25%; после вычитания допуска получен ориентир 89,25%. Пороги фиксируются до итогового теста. Полнота - доля принятых истинных совпадений, включая пропуски. Статистическая оценка учитывает зависимость пар: повторно выбираются целые категории, а не отдельные кадры. На процессоре при 8 ГБ памяти выполнены три обучения с разными начальными состояниями; основное состояние 2027 выбрано заранее.')
    add('small','Таблица 1. Сравнение с визуальными методами без текстовых описаний. Счётчики относятся к решениям, а не к числу уникальных объектов.')
    table=[['Данные и метод','Ложные\nпринятия','Правильные\nсовпадения','Полнота, %','Средний IoU']]
    names=['visual_baseline','visual_strict','gate_text_s2027_full']
    labels=['Без текста','Строгий без текста','С текстовой проверкой']
    for prefix,data in [('Изображения',r),('Видео',v)]:
        for name,label in zip(names,labels):
            x=data[name];recall=x['tpr'] if prefix=='Изображения' else x['macro']['recall']
            table.append([prefix+': '+label,x['fp'],x['tp'],f'{recall*100:.2f}'.replace('.',','),'—' if prefix=='Изображения' else f'{x["macro"]["mean_iou"]:.3f}'.replace('.',',')])
    add('table',rows=table,widths=[205,65,75,65,65])
    add('p','Перенос на полные кадры проверен на 20 заранее выбранных видео DAVIS 2017 [6]: 29 целей и 232 решения. Эталон вырезается из первого кадра, который исключается из оценки. Детектор YOLOv8n предлагает области, DINOv2 выбирает наиболее похожую; пороги перенесены без настройки на DAVIS. Рамка верна при IoU≥0,5. IoU измеряет долю пересечения рамок относительно их объединения; пропуск получает нулевую оценку. Полнота и IoU усредняются по видео на кадрах присутствия цели.')
    add('break');add('head','4 Результаты и их интерпретация')
    add('image',path=OUT/'comparison.png',height=140)
    add('small','Рисунок 3. Число ложных и правильных принятий при неизменных данных. На видео неверная рамка при наличии цели учитывается одновременно как ложная выдача и пропуск.')
    add('p','По сравнению с исходным методом без текстовых описаний дополнительная проверка уменьшила число ложных принятий со 123 до 110, то есть на 10,57%. Число правильных совпадений снизилось со 134 до 128, или на 4,48%; полнота уменьшилась с 83,75 до 80,00%, то есть на 3,75 процентного пункта. Взвешенная сумма ошибок 5FP+FN сократилась с 641 до 582 - на 9,20%. Следовательно, при принятой цене ошибок наблюдается полезный обмен части правильных решений на уменьшение числа ложных принятий, однако допуск потери полноты превышен.')
    add('p','Относительно более строгого визуального порога число ложных принятий уменьшилось со 119 до 110 (на 7,56%), а стоимость ошибок - с 621 до 582 (на 6,28%). Правила не являются вложенными: текст отклонил 13 ложных совпадений строгого контроля, но принял четыре других. Для этого основного сравнения 95%-й интервал снижения риска на одно решение равен [−0,0125; 0,2719] и включает ноль. Дополнительный анализ уже раскрытого теста относительно исходного метода дал интервал [0,0719; 0,3125]; он не заменяет основной критерий и не устраняет превышение допуска полноты.')
    add('p','Отдельное сравнение метрик проведено на одних и тех же текстовых признаках после проектора. Использование расстояния Махаланобиса вместо косинусного уменьшило число ложных принятий со 115 до 110 (на 4,35%), но сократило число правильных совпадений со 131 до 128 (на 2,29%). Это сравнение текстовых метрик, а не замена визуальных признаков DINOv2 текстом. Для трёх начальных состояний обучения стоимость ошибок составила 582, 637 и 582; устойчивое превосходство выбранной метрики не установлено.')
    add('p','На видео по сравнению с исходным методом без текста число ложных рамок снизилось с 29 до 24 (на 17,24%), правильных - со 142 до 141 (на 0,70%). Средняя полнота изменилась с 66,94 до 66,61%, IoU - с 0,627 до 0,621. Против строгого контроля сокращение составило три ложные рамки. Эффект сосредоточен в двух последовательностях, поэтому относительные проценты нельзя считать доказательством универсального улучшения. Четырёх случаев отсутствия цели недостаточно для надёжной оценки частоты ложной тревоги на пустых кадрах.')
    add('head','5 Выводы')
    add('p','Текстовое описание даёт дополнительную информацию для отсеивания части похожих экземпляров. Получен измеримый эффект относительно метода без языковой модели, но заранее установленное преимущество при потере полноты не более двух процентных пунктов не подтверждено. Вклад работы состоит в адаптации обучаемой текстовой метрики и контролируемой оценке её пользы. Дальнейшая проверка должна включать новые независимые съёмки, отдельные эталоны, похожие посторонние объекты и длительные интервалы отсутствия цели; состав теста необходимо фиксировать до получения предсказаний.')
    add('head','Литература')
    refs=[
        '1. Oquab M. et al. DINOv2: Learning Robust Visual Features without Supervision. 2023. arXiv:2304.07193.',
        '2. Reimers N., Gurevych I. Sentence-BERT: Sentence Embeddings using Siamese BERT-Networks // EMNLP-IJCNLP. 2019. P. 3982-3992. DOI: 10.18653/v1/D19-1410.',
        '3. Шабашев В. О. Mahalanobis Concept Drift Detector. https://github.com/sha-bash/mahalanobis-concept-drift. Версия fb3bccd.',
        '4. Ledoit O., Wolf M. A well-conditioned estimator for large-dimensional covariance matrices // Journal of Multivariate Analysis. 2004. Vol. 88(2). P. 365-411.',
        '5. Lai K., Bo L., Ren X., Fox D. A Large-Scale Hierarchical Multi-View RGB-D Object Dataset // ICRA. 2011. https://rgbd-dataset.cs.washington.edu/dataset.html.',
        '6. Pont-Tuset J. et al. The 2017 DAVIS Challenge on Video Object Segmentation. 2017. arXiv:1704.00675.']
    for ref in refs:add('small',ref)
    ST['PaperBody'].fontSize=10.5;ST['PaperBody'].leading=12.3;ST['PaperBody'].spaceAfter=5
    ST['SmallRU'].fontSize=8.4;ST['SmallRU'].leading=10;ST['SmallRU'].spaceAfter=3
    pdf(B,OUT/'report.pdf',paper=True);docx(B,OUT/'report.docx',paper=True)
    d=Document(OUT/'report.docx')
    d.core_properties.title=B[0]['text']
    d.styles['Normal'].font.size=Pt(10.5)
    d.styles['Normal'].paragraph_format.line_spacing=1
    d.styles['Normal'].paragraph_format.space_after=Pt(4)
    d.styles['Caption'].font.size=Pt(8.4)
    d.styles['Caption'].paragraph_format.line_spacing=1
    d.styles['Caption'].paragraph_format.space_after=Pt(3)
    for p in d.paragraphs:
        if p.style.name=='Title' or p._p.xpath('.//w:drawing'):p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        elif p.style.name=='Normal' and p.alignment!=WD_ALIGN_PARAGRAPH.CENTER:p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    d.save(OUT/'report.docx')
    print({'pdf_pages':len(PdfReader(OUT/'report.pdf').pages)})

if __name__=='__main__':main()
